def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_you, last_opp = history[-1]
    # If opponent just defected, retaliate
    if last_opp == 'D':
        # Count consecutive defections by opponent at the end
        def_count = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                def_count += 1
            else:
                break
        # Tit-for-tat with forgiveness: punish for limited rounds, then return to C
        if def_count >= 3:
            # After 3+ straight defections, switch to permanent defection? 
            # But maybe better to try occasional C to re-establish cooperation
            # Use deterministic cycle: D for a while, then C once, then back to D if still D
            return 'D' if (def_count % 4) != 0 else 'C'
        else:
            return 'D'
    # Opponent cooperated last round
    else:
        # Count consecutive cooperations by opponent
        coop_count = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                coop_count += 1
            else:
                break
        # Cooperate back, with occasional random defection to exploit overly cooperative opponents
        # But be cautious: if we've been cooperating and they might defect
        if coop_count >= 5:
            # Against long cooperators, defect occasionally to gain extra points
            if rng.random() < 0.1:
                return 'D'
            else:
                return 'C'
        else:
            return 'C'
